import Foundation

// MARK: - WF4-06 신규 모델 타입

/// 카테고리 필터 pill 아이템.
struct LearnCategory: Hashable, Identifiable {
    let id: String
    let label: String
}

/// 레슨 상태 (듀오링고식 4-상태).
enum LessonStatus: String, Hashable, CaseIterable {
    case completed
    case current
    case pending
    case locked
}

/// 코스 내 개별 레슨 행.
struct LessonRow: Hashable, Identifiable {
    let id: String
    let number: Int
    let title: String
    let durationLabel: String
    let status: LessonStatus
}

/// 한 코스(입문 등)의 메타 + 레슨 목록.
struct CourseSection: Hashable {
    let name: String
    let lessonCount: Int
    let averageMinutes: Int
    let lessons: [LessonRow]
}

/// 추천 아티클 아이템.
struct Article: Hashable, Identifiable {
    let id: String
    let title: String
    let metaLabel: String
}

// MARK: - WeeklyProgress

/// 사주 학습 경로의 주간 진행 요약.
struct WeeklyProgress: Hashable {
    /// 이번 주 완료한 강의 수.
    let completed: Int
    /// 이번 주 목표 강의 수.
    let goal: Int
    /// 연속 학습 일수(예: 3일).
    let streakDays: Int

    /// 진행률 (0.0 ~ 1.0). goal이 0이면 0.0 반환.
    var ratio: Double {
        goal > 0 ? Double(completed) / Double(goal) : 0.0
    }
}

