import XCTest
@testable import Woontech

/// Unit tests for WF4-06 사주 공부 리스트.
final class SajuLearnListTests: XCTestCase {

    // MARK: - TL-01 learnCategories count

    func test_mockProvider_learnCategories_count_is6() {
        let mock = MockSajuLearningPathProvider()
        XCTAssertEqual(mock.learnCategories.count, 6)
    }

    // MARK: - TL-02 learnCategories order

    func test_mockProvider_learnCategories_order_fixed() {
        let mock = MockSajuLearningPathProvider()
        let labels = mock.learnCategories.map { $0.label }
        XCTAssertEqual(labels, ["전체", "입문", "오행", "십성", "대운", "합충"])
    }

    // MARK: - TL-03 initial selectedCategoryId is "all"

    func test_learnListView_initialSelectedCategoryId_isAll() {
        // SajuLearnListView initialises selectedCategoryId to "all".
        // We verify via the first category id in the mock (which is "all").
        let mock = MockSajuLearningPathProvider()
        let firstId = mock.learnCategories.first?.id
        XCTAssertEqual(firstId, "all", "First category must be 'all' — the default selection")
    }

    // MARK: - TL-04 pill selection binding switch

    func test_pill_selection_switchHighlights() {
        // When selectedId changes, only the new id matches.
        var selectedId = "all"
        let categories = MockSajuLearningPathProvider.defaultLearnCategories
        // Simulate tap on "intro"
        selectedId = "intro"
        XCTAssertEqual(selectedId, "intro")
        XCTAssertNotEqual(selectedId, "all", "Previous selection 'all' must be unselected")
    }

    // MARK: - TL-05 ratio = completed / goal

    func test_weeklyProgress_ratio_completedDivGoal() {
        let progress = WeeklyProgress(completed: 3, goal: 5, streakDays: 3)
        XCTAssertEqual(progress.ratio, 0.6, accuracy: 0.0001)
    }

    // MARK: - TL-06 clampedRatio above 1

    func test_weeklyProgress_ratio_clamp_above1() {
        let result = SajuWeeklyProgressBannerView.clampedRatio(1.2)
        XCTAssertEqual(result, 1.0, accuracy: 0.0001)
    }

    // MARK: - TL-07 clampedRatio below 0

    func test_weeklyProgress_ratio_clamp_below0() {
        let result = SajuWeeklyProgressBannerView.clampedRatio(-0.1)
        XCTAssertEqual(result, 0.0, accuracy: 0.0001)
    }

    // MARK: - TL-08 ratio goal zero returns 0

    func test_weeklyProgress_ratio_goalZero_returns0() {
        let progress = WeeklyProgress(completed: 0, goal: 0, streakDays: 0)
        XCTAssertEqual(progress.ratio, 0.0, accuracy: 0.0001)
    }

    // MARK: - TL-09 streak badge hidden when 0

    func test_weeklyBanner_streakBadge_hidden_when0() {
        let streakDays = 0
        XCTAssertFalse(streakDays > 0, "streakDays=0 should NOT show badge")
    }

    // MARK: - TL-10 streak badge shown when 3

    func test_weeklyBanner_streakBadge_shown_when3() {
        let streakDays = 3
        XCTAssertTrue(streakDays > 0, "streakDays=3 should show badge")
    }

    // MARK: - TL-11 completed/total text binding

    func test_weeklyBanner_text_completed_total_binding() {
        let mock = MockSajuLearningPathProvider()
        let progress = mock.weeklyProgress
        let text = "\(progress.completed) / \(progress.goal)강 완료"
        XCTAssertEqual(text, "3 / 5강 완료")
    }

    // MARK: - TL-12 course header name binding

    func test_courseHeader_name_binding() {
        let mock = MockSajuLearningPathProvider()
        let headerText = "\(mock.introductoryCourse.name) 코스"
        XCTAssertEqual(headerText, "입문 코스")
    }

    // MARK: - TL-13 course header lessonCount + averageMinutes

    func test_courseHeader_lessonCount_averageMinutes() {
        let mock = MockSajuLearningPathProvider()
        let course = mock.introductoryCourse
        let metaText = "\(course.lessonCount)강 · 평균 \(course.averageMinutes)분"
        XCTAssertEqual(metaText, "7강 · 평균 3분")
    }

    // MARK: - TL-14 course list count matches lessonCount

    func test_courseList_count_matches_lessonCount() {
        let mock = MockSajuLearningPathProvider()
        let course = mock.introductoryCourse
        XCTAssertEqual(course.lessons.count, course.lessonCount)
        XCTAssertEqual(course.lessons.count, 7)
    }

    // MARK: - TL-15 statusKorean completed

    func test_lessonRow_statusKorean_completed() {
        XCTAssertEqual(SajuLessonRowCardView.statusKorean(.completed), "완료")
    }

    // MARK: - TL-16 statusKorean current

    func test_lessonRow_statusKorean_current() {
        XCTAssertEqual(SajuLessonRowCardView.statusKorean(.current), "현재")
    }

    // MARK: - TL-17 statusKorean pending

    func test_lessonRow_statusKorean_pending() {
        XCTAssertEqual(SajuLessonRowCardView.statusKorean(.pending), "미완료")
    }

    // MARK: - TL-18 statusKorean locked

    func test_lessonRow_statusKorean_locked() {
        XCTAssertEqual(SajuLessonRowCardView.statusKorean(.locked), "잠김")
    }

    // MARK: - TL-19 current meta includes 이어보기

    func test_lessonRow_current_meta_includes_이어보기() {
        let mock = MockSajuLearningPathProvider()
        let currentLesson = mock.introductoryCourse.lessons.first(where: { $0.status == .current })!
        let metaLine = currentLesson.status == .current
            ? "\(currentLesson.durationLabel) · 이어보기"
            : currentLesson.durationLabel
        XCTAssertTrue(metaLine.contains("이어보기"))
    }

    // MARK: - TL-20 pending meta excludes 이어보기

    func test_lessonRow_pending_meta_no_이어보기() {
        // Lessons 5,6,7 are locked, not pending. Use a manual pending lesson.
        let pendingLesson = LessonRow(id: "LP", number: 3, title: "test", durationLabel: "3분", status: .pending)
        let metaLine = pendingLesson.status == .current
            ? "\(pendingLesson.durationLabel) · 이어보기"
            : pendingLesson.durationLabel
        XCTAssertFalse(metaLine.contains("이어보기"))
    }

    // MARK: - TL-21 handleLessonTap completed fires route

    func test_handleLessonTap_completed_firesRoute() {
        var capturedRoute: SajuRoute? = nil
        let lesson = LessonRow(id: "L1", number: 1, title: "사주란", durationLabel: "3분", status: .completed)
        let onNavigate: (SajuRoute) -> Void = { capturedRoute = $0 }
        // Simulate the logic in SajuLearnListView.handleLessonTap
        switch lesson.status {
        case .completed, .current, .pending:
            onNavigate(.lesson(id: lesson.id))
        case .locked:
            break
        }
        XCTAssertEqual(capturedRoute, .lesson(id: "L1"))
    }

    // MARK: - TL-22 handleLessonTap current fires route

    func test_handleLessonTap_current_firesRoute() {
        var capturedRoute: SajuRoute? = nil
        let lesson = LessonRow(id: "L4", number: 4, title: "일간", durationLabel: "5분", status: .current)
        let onNavigate: (SajuRoute) -> Void = { capturedRoute = $0 }
        switch lesson.status {
        case .completed, .current, .pending:
            onNavigate(.lesson(id: lesson.id))
        case .locked:
            break
        }
        XCTAssertEqual(capturedRoute, .lesson(id: "L4"))
    }

    // MARK: - TL-23 handleLessonTap pending fires route

    func test_handleLessonTap_pending_firesRoute() {
        var capturedRoute: SajuRoute? = nil
        let lesson = LessonRow(id: "LP", number: 3, title: "pending", durationLabel: "3분", status: .pending)
        let onNavigate: (SajuRoute) -> Void = { capturedRoute = $0 }
        switch lesson.status {
        case .completed, .current, .pending:
            onNavigate(.lesson(id: lesson.id))
        case .locked:
            break
        }
        XCTAssertEqual(capturedRoute, .lesson(id: "LP"))
    }

    // MARK: - TL-24 handleLessonTap locked does NOT fire route

    func test_handleLessonTap_locked_doesNotFireRoute() {
        var capturedRoute: SajuRoute? = nil
        let lesson = LessonRow(id: "L5", number: 5, title: "locked", durationLabel: "4분", status: .locked)
        let onNavigate: (SajuRoute) -> Void = { capturedRoute = $0 }
        switch lesson.status {
        case .completed, .current, .pending:
            onNavigate(.lesson(id: lesson.id))
        case .locked:
            break
        }
        XCTAssertNil(capturedRoute, "Locked lesson tap must NOT fire navigate")
    }

    // MARK: - TL-25 recommendedArticles empty hides section

    func test_recommendedArticles_sectionHidden_whenEmpty() {
        let mock = MockSajuLearningPathProvider(recommendedArticles: [])
        XCTAssertTrue(mock.recommendedArticles.isEmpty, "Empty articles should hide section")
    }

    // MARK: - TL-26 recommendedArticles count matches provider

    func test_recommendedArticles_count_matches_provider() {
        let mock = MockSajuLearningPathProvider()
        XCTAssertEqual(mock.recommendedArticles.count, 2)
    }

    // MARK: - TL-27 article tap no route change

    func test_articleCard_tap_noRouteChange() {
        var capturedRoute: SajuRoute? = nil
        // SajuLearnArticleCardView onTap is no-op in SajuLearnListView
        let noOpTap: () -> Void = { /* no-op */ }
        noOpTap()
        XCTAssertNil(capturedRoute, "Article card tap must not fire navigate")
    }

    // MARK: - TL-28 lesson4 status is current

    func test_mockProvider_introductoryCourse_lesson4_isCurrent() {
        let mock = MockSajuLearningPathProvider()
        let lesson4 = mock.introductoryCourse.lessons[3]
        XCTAssertEqual(lesson4.status, .current)
    }

    // MARK: - TL-29 lesson5 status is locked

    func test_mockProvider_introductoryCourse_lesson5_isLocked() {
        let mock = MockSajuLearningPathProvider()
        let lesson5 = mock.introductoryCourse.lessons[4]
        XCTAssertEqual(lesson5.status, .locked)
    }

    // MARK: - TL-30 clampedRatio 0.6

    func test_weeklyProgressBannerView_clampedRatio_0_6() {
        let result = SajuWeeklyProgressBannerView.clampedRatio(0.6)
        XCTAssertEqual(result, 0.6, accuracy: 0.0001)
    }
}

import XCTest

/// UI tests for WF4-06 사주 공부 리스트.
///
/// 공통 설정: `-resetOnboarding -openSajuTab` 실행 후
/// `SajuNavPush_learn` 버튼으로 `SajuLearnListView` 진입.
final class SajuLearnListUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
    }

    // MARK: - Helpers

    private func launchSajuTab(extraArgs: [String] = [], extraEnv: [String: String] = [:]) {
        app.launchArguments = ["-resetOnboarding", "-openSajuTab"] + extraArgs
        for (key, value) in extraEnv {
            app.launchEnvironment[key] = value
        }
        app.launch()
        XCTAssertTrue(
            app.otherElements["SajuTabRoot"].waitForExistence(timeout: 5),
            "SajuTabRoot must exist after launch"
        )
    }

    /// SajuLearnListView까지 진입한다.
    private func launchLearnList(extraArgs: [String] = [], extraEnv: [String: String] = [:]) {
        launchSajuTab(extraArgs: extraArgs, extraEnv: extraEnv)
        let btn = app.buttons["SajuNavPush_learn"]
        XCTAssertTrue(btn.waitForExistence(timeout: 3), "SajuNavPush_learn must exist")
        btn.tap()
        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5),
            "SajuLearnListView must appear"
        )
    }

    // MARK: - TU-L01 Navigate from below-fold "전체 ›"

    func test_navigate_fromBelowFold_allButton() {
        launchSajuTab()
        let scroll = app.scrollViews["SajuTabContent"]
        XCTAssertTrue(scroll.waitForExistence(timeout: 5))
        scroll.swipeUp()
        scroll.swipeUp()
        let allBtn = app.buttons["SajuStudyHeaderAllButton"]
        XCTAssertTrue(allBtn.waitForExistence(timeout: 5))
        allBtn.tap()
        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5),
            "SajuLearnListView should appear after tapping 전체 › button"
        )
    }

    // MARK: - TU-L02 Navigate from course card

    func test_navigate_fromBelowFold_courseCard() {
        launchSajuTab()
        let scroll = app.scrollViews["SajuTabContent"]
        XCTAssertTrue(scroll.waitForExistence(timeout: 5))
        scroll.swipeUp()
        scroll.swipeUp()
        let courseCard = app.buttons["SajuCourseCard_입문"]
        XCTAssertTrue(courseCard.waitForExistence(timeout: 5))
        courseCard.tap()
        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5),
            "SajuLearnListView should appear after tapping SajuCourseCard_입문"
        )
    }

    // MARK: - TU-L03 NavBar title

    func test_navBar_title_사주공부() {
        launchLearnList()
        XCTAssertTrue(app.navigationBars["사주 공부"].waitForExistence(timeout: 3))
    }

    // MARK: - TU-L04 NavBar search button exists

    func test_navBar_searchButton_exists() {
        launchLearnList()
        XCTAssertTrue(
            app.buttons["SajuLearnSearchButton"].waitForExistence(timeout: 3),
            "SajuLearnSearchButton must exist"
        )
    }

    // MARK: - TU-L05 NavBar search button tap is no-op

    func test_navBar_searchButton_tap_isNoOp() {
        launchLearnList()
        let searchBtn = app.buttons["SajuLearnSearchButton"]
        XCTAssertTrue(searchBtn.waitForExistence(timeout: 3))
        searchBtn.tap()
        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 3),
            "SajuLearnListView should still be on screen after search tap (no push)"
        )
    }

    // MARK: - TU-L06 Category pills count = 6

    func test_categoryPills_count_is6() {
        launchLearnList()
        let pillIds = ["all", "intro", "elements", "tenGods", "daewoon", "hapchung"]
        for id in pillIds {
            XCTAssertTrue(
                app.buttons["SajuLearnCategoryPill_\(id)"].waitForExistence(timeout: 3),
                "SajuLearnCategoryPill_\(id) must exist"
            )
        }
    }

    // MARK: - TU-L07 Category pills order

    func test_categoryPills_order_fixed() {
        launchLearnList()
        let pillIds = ["all", "intro", "elements", "tenGods", "daewoon", "hapchung"]
        var prevMaxX: CGFloat = 0
        for id in pillIds {
            let pill = app.buttons["SajuLearnCategoryPill_\(id)"]
            XCTAssertTrue(pill.waitForExistence(timeout: 3))
            let minX = pill.frame.minX
            XCTAssertGreaterThan(minX, prevMaxX - 1,
                "Pill \(id) must be to the right of previous pill")
            prevMaxX = pill.frame.maxX
        }
    }

    // MARK: - TU-L08 Initial selection is "전체"

    func test_categoryPills_initialSelection_전체() {
        launchLearnList()
        let allPill = app.buttons["SajuLearnCategoryPill_all"]
        XCTAssertTrue(allPill.waitForExistence(timeout: 3))
        XCTAssertTrue(
            allPill.label.contains("선택됨"),
            "Initial pill 'all' must have '선택됨' in its accessibility label"
        )
    }

    // MARK: - TU-L09 Pill selection switch

    func test_categoryPills_switchSelection() {
        launchLearnList()
        let introPill = app.buttons["SajuLearnCategoryPill_intro"]
        XCTAssertTrue(introPill.waitForExistence(timeout: 3))
        introPill.tap()
        XCTAssertTrue(
            introPill.label.contains("선택됨"),
            "After tap, intro pill should be selected"
        )
        let allPill = app.buttons["SajuLearnCategoryPill_all"]
        XCTAssertTrue(allPill.waitForExistence(timeout: 3))
        XCTAssertTrue(
            allPill.label.contains("선택 안됨"),
            "After intro tap, all pill should be unselected"
        )
    }

    // MARK: - TU-L10 Weekly banner exists

    func test_weeklyBanner_exists() {
        launchLearnList()
        XCTAssertTrue(
            app.otherElements["SajuLearnWeeklyBanner"].waitForExistence(timeout: 3),
            "SajuLearnWeeklyBanner must exist"
        )
    }

    // MARK: - TU-L11 Streak badge visible (default)

    func test_weeklyBanner_streakBadge_visible_default() {
        launchLearnList()
        let badge = app.buttons["SajuLearnStreakBadge"]
            .firstMatch
        let textBadge = app.otherElements["SajuLearnStreakBadge"]
            .firstMatch
        let streakBadge = badge.exists ? badge : textBadge
        // Since SajuLearnStreakBadge is a Text inside a Capsule background it may appear as staticText
        let staticBadge = app.staticTexts.matching(NSPredicate(format: "identifier == 'SajuLearnStreakBadge'")).firstMatch
        let anyBadge = streakBadge.exists ? streakBadge : staticBadge
        XCTAssertTrue(
            app.otherElements["SajuLearnWeeklyBanner"].waitForExistence(timeout: 3)
        )
        // Check banner label contains streak info
        let banner = app.otherElements["SajuLearnWeeklyBanner"]
        XCTAssertTrue(banner.label.contains("연속 3일") || banner.label.contains("3일"),
            "Banner label should mention streak days")
        _ = anyBadge
    }

    // MARK: - TU-L12 Streak badge hidden when streakDays=0

    func test_weeklyBanner_streakBadge_hidden_streakDays0() {
        launchLearnList(extraArgs: ["-sajuLearnStreakZero"])
        XCTAssertTrue(app.otherElements["SajuLearnWeeklyBanner"].waitForExistence(timeout: 3))
        let badge = app.staticTexts.matching(NSPredicate(format: "identifier == 'SajuLearnStreakBadge'")).firstMatch
        XCTAssertFalse(badge.exists, "SajuLearnStreakBadge must not exist when streakDays=0")
    }

    // MARK: - TU-L13 Weekly banner completed/total text

    func test_weeklyBanner_completedTotalText() {
        launchLearnList()
        let label = app.staticTexts["3 / 5강 완료"]
        if !label.waitForExistence(timeout: 3) {
            // Check if it exists somewhere in the tree
            let predicate = NSPredicate(format: "label CONTAINS '3 / 5강 완료'")
            XCTAssertTrue(
                app.staticTexts.matching(predicate).firstMatch.waitForExistence(timeout: 3),
                "Text '3 / 5강 완료' must appear in the banner"
            )
        }
    }

    // MARK: - TU-L14 Course header text

    func test_courseHeader_text() {
        launchLearnList()
        let header = app.otherElements["SajuLearnCourseHeader"]
        XCTAssertTrue(header.waitForExistence(timeout: 3))
        XCTAssertTrue(header.label.contains("입문 코스"),
            "Course header must contain '입문 코스'")
        XCTAssertTrue(header.label.contains("7강"),
            "Course header must mention '7강'")
    }

    // MARK: - TU-L15 Course list 7 cards

    func test_courseList_7cards_exist() {
        launchLearnList()
        for i in 1...7 {
            let card = app.buttons["SajuLearnLessonCard_L\(i)"]
            XCTAssertTrue(
                card.waitForExistence(timeout: 3),
                "SajuLearnLessonCard_L\(i) must exist"
            )
        }
    }

    // MARK: - TU-L16 Completed card label contains "완료"

    func test_lessonCard_completed_accessibilityLabel() {
        launchLearnList()
        let card = app.buttons["SajuLearnLessonCard_L1"]
        XCTAssertTrue(card.waitForExistence(timeout: 3))
        XCTAssertTrue(card.label.contains("완료"),
            "L1 card label must contain '완료'")
    }

    // MARK: - TU-L17 Current card label contains "이어보기"

    func test_lessonCard_current_continueLabel() {
        launchLearnList()
        let card = app.buttons["SajuLearnLessonCard_L4"]
        XCTAssertTrue(card.waitForExistence(timeout: 3))
        XCTAssertTrue(card.label.contains("이어보기"),
            "L4 (current) card must mention '이어보기'")
    }

    // MARK: - TU-L18 Locked card label contains "잠김"

    func test_lessonCard_locked_label() {
        launchLearnList()
        let card = app.buttons["SajuLearnLessonCard_L5"]
        XCTAssertTrue(card.waitForExistence(timeout: 3))
        XCTAssertTrue(card.label.contains("잠김"),
            "L5 (locked) card must mention '잠김'")
    }

    // MARK: - TU-L19 Completed card tap pushes lesson

    func test_lessonCard_completed_tap_pushesLesson() {
        launchLearnList()
        let card = app.buttons["SajuLearnLessonCard_L1"]
        XCTAssertTrue(card.waitForExistence(timeout: 3))
        card.tap()
        // After push, lesson placeholder shows "L1" identifier
        let lessonDest = app.otherElements["SajuPlaceholderDestination_lesson"]
        XCTAssertTrue(lessonDest.waitForExistence(timeout: 5),
            "Lesson destination must appear after tapping L1")
    }

    // MARK: - TU-L20 Current card tap pushes lesson

    func test_lessonCard_current_tap_pushesLesson() {
        launchLearnList()
