// MARK: - Locked trait modifier

private struct LockedTraitModifier: ViewModifier {
    let isLocked: Bool
    func body(content: Content) -> some View {
        if isLocked {
            content.accessibilityAddTraits(.notEnabled)
        } else {
            content
        }
    }
}

